document.getElementById('tuneRows').addEventListener('input',e=>{const id=e.target&&e.target.id||'';if(!id.startsWith('t_'))return;const k=id.slice(2),kind=KIND_OF[k];if(!kind||!ALTON[kind])return;ALT[kind][k]=+e.target.value;saveAlt()});
function lookBtns(){const on=!!ALTON[ST.kind];const a=document.getElementById('lkCur'),b=document.getElementById('lkNew');if(a)a.setAttribute('aria-pressed',!on);if(b)b.setAttribute('aria-pressed',on)}
const GAMECOL=window.__TCOL;/* Build 343: 'Current' is now the game's painted look */
