 $('stPaint').onclick=e=>{const on=e.target.getAttribute('aria-pressed')!=='true';e.target.setAttribute('aria-pressed',on);if(PAINT)PAINT.enabled=on};if(!PAINT)$('stPaint').hidden=true;
