 $('stTune').onclick=()=>{const t=$('tune');t.hidden=!t.hidden;$('stTune').setAttribute('aria-pressed',!t.hidden)};$('stCam').onclick=()=>{ST.yaw=.6;ST.pitch=.18;ST.dist=.75;ST.pan.set(0,0,0)};
